const invoices = ctx.api.object('demoorder_invoice');
const inv = await invoices.findOne({ where: { id: ctx.recordId } });
if (!inv) throw { code: 'INVOICE_NOT_FOUND' };
const balance = Number(inv.balance || 0);
if (!(inv.status === 'open' || inv.status === 'partially_paid') || !(balance > 0)) {
  throw { code: 'NOTHING_TO_WRITE_OFF' };
}
const today = new Date().toISOString().slice(0, 10);
await invoices.update({ id: ctx.recordId, write_off_amount: balance, written_off_on: today });
return { written_off: balance };

